record User(String name, int age, boolean active) {}

List<User> users = List.of(
    new User("Hen", 38, true),
    new User("Dana", 25, false),
    new User("Avi", 30, true)
);

Predicate<User> isActive = user -> user.active();

List<User> activeUsers = users.stream()
    .filter(isActive)
    .toList();

Function<User, String> toName = user -> user.name();

List<String> names = users.stream()
    .map(toName)
    .toList();

Supplier<User> defaultUser =
    () -> new User("Unknown", 0, false);

User user = findUserById("123")
    .orElseGet(defaultUser);

BiFunction<String, Integer, User> createUser =
    (name, age) -> new User(name, age, true);

User user = createUser.apply("Hen", 38);

